596 |         assert!(cache.size().await >= 1);
597 |         let hit = cache
598 |             .get_with_key(&TestKey::<Vec<u8>>::new("k-63"))
599 |             .await
600 |             .is_some()
601 |             || cache
602 |                 .get_with_key(&TestKey::<Vec<u8>>::new("k-62"))
603 |                 .await
604 |                 .is_some();
